import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                result[key] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return result

b = extract(baseline)
a = extract(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))
changes = []
unchanged = []
for k in all_keys:
    proj, tfm, pkg = k
    bv = b.get(k)
    av = a.get(k)
    if bv and av:
        if bv[1] != av[1]:
            changes.append((proj, tfm, pkg, bv[1], av[1], 'Aligned to highest version'))
        else:
            unchanged.append((proj, tfm, pkg, av[1]))
    elif bv and not av:
        changes.append((proj, tfm, pkg, bv[1], '-', 'Removed'))
    elif av and not bv:
        changes.append((proj, tfm, pkg, '-', av[1], 'Added'))

print('=== CHANGES ===')
if changes:
    print(f'{\"Project\":<15} {\"TFM\":<8} {\"Package\":<50} {\"Before\":<12} {\"After\":<12} Status')
    for c in changes:
        print(f'{c[0]:<15} {c[1]:<8} {c[2]:<50} {c[3]:<12} {c[4]:<12} {c[5]}')
else:
    print('None')

print()
print('=== UNCHANGED ===')
print(f'{\"Project\":<15} {\"TFM\":<8} {\"Package\":<50} {\"Version\"}')
for u in unchanged:
    print(f'{u[0]:<15} {u[1]:<8} {u[2]:<50} {u[3]}')
